"""Session 09f check: # column wide enough at 1440/1024/768, plus title-column share."""

from playwright.sync_api import sync_playwright

BASE = "http://127.0.0.1:18808"
OUT = "/Users/wanderer/Project/oceanbase/powercontext-camp/.camp/wt/eco-qoder-site/qoder/.cache/scratch"

JS = """
() => {
  const table = document.querySelector("table.sessions");
  const rows = [...table.querySelectorAll("tr")];
  let overflowCells = [];
  let colWidths = [];
  for (const tr of rows) {
    const cells = [...tr.children];
    if (cells.length === 5 && !colWidths.length)
      colWidths = cells.map(c => c.getBoundingClientRect().width);
    for (const c of cells) {
      if (c.scrollWidth > c.clientWidth)
        overflowCells.push({text: c.innerText.trim().slice(0, 30),
                            sw: c.scrollWidth, cw: c.clientWidth});
    }
  }
  const total = colWidths.reduce((a, b) => a + b, 0);
  const tableW = table.getBoundingClientRect().width;
  const badRow = rows.find(r => r.innerText.includes("05（中止）"));
  const idCell = badRow ? badRow.children[0] : null;
  return {
    overflow: overflowCells,
    colWidths: colWidths.map(w => Math.round(w * 10) / 10),
    tableW: Math.round(tableW * 10) / 10,
    titlePct: Math.round(colWidths[1] / tableW * 1000) / 10,
    idCell: idCell ? {sw: idCell.scrollWidth, cw: idCell.clientWidth,
                      wrapped: idCell.clientHeight > idCell.firstElementChild
                        ? idCell.clientHeight / idCell.firstElementChild.clientHeight : 1}
                   : null,
  };
}
"""

with sync_playwright() as p:
    b = p.chromium.launch(channel="chrome", headless=True)
    for w in (1440, 1024, 768):
        pg = b.new_page(viewport={"width": w, "height": 900})
        pg.goto(BASE + "/", wait_until="networkidle")
        pg.wait_for_timeout(1200)
        r = pg.evaluate(JS)
        print(f"--- {w}px ---")
        print("overflow cells:", r["overflow"])
        print("col widths:", r["colWidths"], "tableW:", r["tableW"])
        print("title pct:", r["titlePct"])
        print("05(中止) id cell:", r["idCell"])
        if w == 1440:
            pg.locator("table.sessions").screenshot(
                path=f"{OUT}/clip-09f-desktop-sessions.png")
        pg.close()
    b.close()

print("done")

